# Source for q/ae-anatomy-views.js: Anatomy, Physiology, Echo views.
AN="Anatomy"; PH="Physiology"; EV="Echo views"
Q=[
# --- Anatomy: layers and position ---
(AN,"The three layers of the heart wall, from inside out, are:","Endocardium, myocardium and epicardium",["Epicardium, endocardium and myocardium","Myocardium, pericardium and endocardium","Intima, media and adventitia"],"The epicardium is also the visceral layer of the serous pericardium.","F"),
(AN,"The pericardial space lies between:","The visceral and parietal layers of the serous pericardium",["The myocardium and endocardium","The fibrous pericardium and the lung","The epicardium and myocardium"],"It normally contains about 15 to 50 mL of fluid that lubricates the heart.","F"),
(AN,"The outer tough layer that anchors the heart to the diaphragm and great vessels is the:","Fibrous pericardium",["Visceral pericardium","Endocardium","Epicardial fat"],"Its stiffness is why rapidly collecting fluid causes tamponade.","F"),
(AN,"The cardiac apex normally lies at about the:","Fifth left intercostal space, near the midclavicular line",["Second right intercostal space","Suprasternal notch","Xiphoid process"],"This is where the apical window is found.","F"),
(AN,"The most anterior chamber of the heart is the:","Right ventricle",["Left atrium","Left ventricle","Right atrium"],"It lies just behind the sternum, which is why it is closest to the transducer in parasternal views.","F"),
(AN,"The most posterior chamber of the heart is the:","Left atrium",["Right ventricle","Right atrium","Left ventricle"],"It sits in front of the esophagus, which is why TEE images it so well.","F"),
(AN,"The fibrous cardiac skeleton:","Supports the four valve rings and electrically separates the atria from the ventricles",["Pumps blood","Covers the outer heart","Lines the chambers"],"Only the AV node and bundle of His normally conduct impulses across it.","C"),
# --- Valves ---
(AN,"The mitral valve's posterior leaflet is divided into scallops named:","P1, P2 and P3",["A1, A2 and A3 only","Right, left and non-coronary","Septal, anterior and posterior"],"P1 is lateral (near the anterolateral commissure) and P3 is medial. The opposite anterior segments are A1 to A3.","F"),
(AN,"The anterior mitral leaflet compared with the posterior leaflet is:","Longer, but attached to a smaller part of the annulus",["Shorter and attached to most of the annulus","Identical in size","Absent in most people"],"The posterior leaflet is short but wraps around about two-thirds of the annulus.","C"),
(AN,"The two mitral commissures are:","Anterolateral and posteromedial",["Septal and lateral","Superior and inferior","Right and left coronary"],"Rheumatic mitral stenosis fuses these commissures.","F"),
(AN,"The three tricuspid leaflets are:","Anterior, septal and posterior",["Right, left and non-coronary","Anterior, posterior and lateral","A1, A2 and A3"],"The septal leaflet attaches to the ventricular septum, a feature of the morphologic RV.","F"),
(AN,"The three aortic cusps are named:","Right coronary, left coronary and non-coronary",["Anterior, septal and posterior","Anterolateral and posteromedial","P1, P2 and P3"],"The cusps are named for the coronary arteries arising from their sinuses.","F"),
(AN,"The chordae tendineae connect the:","AV valve leaflets to the papillary muscles",["Aortic cusps to the aorta","Atria to the ventricles","Pericardium to the diaphragm"],"They stop the mitral and tricuspid leaflets from prolapsing into the atria in systole.","F"),
(AN,"The two papillary muscles of the left ventricle are:","Anterolateral and posteromedial",["Anterior, posterior and septal","Superior and inferior","Medial and lateral only in the RV"],"The RV has three papillary muscle groups: anterior, posterior and septal.","F"),
(AN,"The semilunar valves are the:","Aortic and pulmonic valves",["Mitral and tricuspid valves","Mitral and aortic valves","Tricuspid and pulmonic valves"],"They have half-moon cusps and no chordae.","F"),
(AN,"The sinotubular junction is:","Where the sinuses of Valsalva meet the tubular ascending aorta",["The mitral annulus","The LVOT","The aortic arch"],"Loss of a clear STJ is a sign of Marfan syndrome.","F"),
(AN,"The most anterior heart valve is the:","Pulmonic valve",["Mitral valve","Aortic valve","Tricuspid valve"],"It sits highest and most anterior, in front of and to the left of the aortic valve.","F"),
# --- Septa, atria, veins ---
(AN,"The fossa ovalis is:","A thin depression in the interatrial septum, the remnant of the fetal foramen ovale",["A ridge in the right atrium","The opening of the coronary sinus","Part of the ventricular septum"],"Secundum ASDs and PFOs occur here.","F"),
(AN,"The membranous part of the ventricular septum is:","A small, thin area just below the aortic valve",["Most of the septum","Near the apex","In the RV outflow tract only"],"Perimembranous VSDs occur around it.","F"),
(AN,"How many pulmonary veins usually drain into the left atrium?","Four",["Two","One","Six"],"Right and left upper and lower veins. The right upper vein is often sampled for pulmonary vein Doppler.","F"),
(AN,"The coronary sinus drains into the:","Right atrium",["Left atrium","Left ventricle","Superior vena cava"],"Its opening has a small valve called the Thebesian valve.","F"),
(AN,"The left atrial appendage is:","Long, narrow and finger-like",["Broad and triangular","Absent","Inside the left ventricle"],"The right atrial appendage is broad and triangular. LAA is the usual site of thrombus in AF.","F"),
(AN,"The inferior vena cava enters the:","Right atrium",["Left atrium","Right ventricle","Coronary sinus"],"Hepatic veins join the IVC just below the diaphragm.","F"),
(AN,"The ascending aorta lies:","To the right of and behind the main pulmonary artery",["To the left of the pulmonary artery","In front of the RV","Behind the left atrium"],"The great arteries cross: the RVOT runs anterior to the aorta.","C"),
(AN,"The main pulmonary artery divides into:","Right and left pulmonary arteries",["Innominate and carotid arteries","Coronary arteries","Pulmonary veins"],"The bifurcation is seen in a parasternal short-axis view at the base.","F"),
# --- Coronary anatomy ---
(AN,"The left main coronary artery divides into the:","Left anterior descending and left circumflex arteries",["Right coronary and posterior descending","Diagonal and marginal only","Obtuse marginal and acute marginal"],"Some people also have a ramus intermedius between them.","F"),
(AN,"Coronary dominance is defined by which artery gives rise to the:","Posterior descending artery",["Left anterior descending","Obtuse marginal","Sinoatrial nodal artery"],"About 70% to 80% of people are right dominant.","F"),
(AN,"Most coronary blood flow to the LV occurs during:","Diastole",["Systole","Isovolumic contraction","Atrial systole only"],"In systole the contracting muscle squeezes the intramyocardial vessels.","F"),
(AN,"The AV node usually receives blood from the:","Right coronary artery, in right-dominant hearts",["Left anterior descending","Left main","Diagonal branch"],"This is why inferior MIs can cause heart block.","F"),
# --- Conduction ---
(AN,"The normal pacemaker of the heart is the:","Sinoatrial node in the right atrium",["AV node","Bundle of His","Purkinje fibers"],"It lies near where the SVC enters the right atrium.","F"),
(AN,"The AV node is located in the:","Triangle of Koch, near the coronary sinus opening in the RA",["Left atrial appendage","LV apex","Aortic root"],"It delays the impulse so the atria can finish emptying.","C"),
(AN,"The correct order of electrical conduction is:","SA node, AV node, bundle of His, bundle branches, Purkinje fibers",["AV node, SA node, Purkinje fibers, bundle of His","Purkinje fibers, bundle branches, SA node","Bundle of His, SA node, AV node"],"Disease anywhere along this path causes blocks or arrhythmias.","F"),
# --- Fetal circulation ---
(AN,"In the fetus, the foramen ovale allows blood to flow from:","Right atrium to left atrium",["Left atrium to right atrium","Aorta to pulmonary artery","LV to RV"],"Oxygenated blood from the placenta bypasses the lungs.","F"),
(AN,"In the fetus, the ductus arteriosus carries blood from the:","Pulmonary artery to the descending aorta",["Aorta to pulmonary artery","LA to RA","IVC to RA"],"High pulmonary resistance in the fetus diverts blood away from the lungs.","F"),
(AN,"The ductus venosus in the fetus:","Lets placental blood bypass the liver and enter the IVC",["Connects the aorta and PA","Connects the atria","Drains the coronary sinus"],"It closes after birth and becomes the ligamentum venosum.","C"),
(AN,"After birth, the foramen ovale closes because:","Left atrial pressure rises above right atrial pressure",["Right atrial pressure rises","The lungs stop working","The ductus opens wider"],"Lung expansion increases pulmonary flow and LA return, pushing the flap shut.","F"),
(AN,"The ductus arteriosus normally closes after birth because of:","Rising oxygen levels and falling prostaglandin levels",["Falling oxygen levels","Rising prostaglandins","Increased pulmonary resistance"],"It becomes the ligamentum arteriosum.","C"),
# --- Physiology: cardiac cycle ---
(PH,"The first heart sound (S1) is caused by:","Closure of the mitral and tricuspid valves",["Closure of the aortic and pulmonic valves","Rapid ventricular filling","Atrial contraction"],"S1 marks the start of ventricular systole.","F"),
(PH,"The second heart sound (S2) is caused by:","Closure of the aortic and pulmonic valves",["Closure of the mitral and tricuspid valves","Opening of the AV valves","Atrial contraction"],"S2 marks the end of ejection and the start of diastole.","F"),
(PH,"Physiologic splitting of S2 is heard during:","Inspiration",["Expiration","Breath-holding","Valsalva strain"],"Increased venous return on inspiration delays pulmonic valve closure.","F"),
(PH,"An S3 heart sound in an older adult suggests:","Heart failure with rapid early filling into a dilated ventricle",["Normal aging","Aortic stenosis","Pericarditis"],"An S3 can be normal in children and young athletes.","F"),
(PH,"An S4 heart sound is caused by:","Atrial contraction into a stiff ventricle",["Mitral valve closure","Aortic valve closure","Early rapid filling"],"It is heard in LVH, hypertension and ischemia. It is absent in atrial fibrillation.","F"),
(PH,"On the ECG, the P wave represents:","Atrial depolarization, which precedes atrial contraction",["Ventricular depolarization","Ventricular repolarization","AV nodal delay"],"The mitral A wave follows the P wave.","F"),
(PH,"On the ECG, the QRS complex represents:","Ventricular depolarization, just before ventricular contraction",["Atrial depolarization","Ventricular repolarization","Atrial repolarization only"],"End-diastole is marked at the onset of QRS.","F"),
(PH,"The T wave on the ECG corresponds approximately to:","Ventricular repolarization, near the end of systole",["Atrial contraction","Early diastole only","Isovolumic contraction"],"End-systole is near the end of the T wave.","F"),
(PH,"During isovolumic contraction:","All four valves are closed and ventricular pressure rises rapidly",["The aortic valve is open","The mitral valve is open","Ventricular volume falls"],"Once LV pressure exceeds aortic pressure, the aortic valve opens.","F"),
(PH,"The aortic valve opens when:","LV pressure exceeds aortic pressure",["LA pressure exceeds LV pressure","Aortic pressure exceeds LV pressure","The mitral valve opens"],"It closes when aortic pressure exceeds falling LV pressure.","F"),
(PH,"The mitral valve opens when:","LV pressure falls below LA pressure",["LV pressure exceeds aortic pressure","Aortic pressure exceeds LA pressure","The aortic valve opens"],"This ends isovolumic relaxation and starts early filling.","F"),
(PH,"Normal pressures in the right ventricle are about:","25/5 mmHg",["120/10 mmHg","80/40 mmHg","10/0 mmHg"],"The pulmonary artery is about 25/10 mmHg.","F"),
(PH,"Normal left ventricular pressures are about:","120/10 mmHg",["25/5 mmHg","60/30 mmHg","200/50 mmHg"],"LV end-diastolic pressure is normally under about 12 mmHg.","F"),
(PH,"Normal right atrial (central venous) pressure is about:","2 to 6 mmHg",["20 to 30 mmHg","50 mmHg","Over 100 mmHg"],"Echo estimates RA pressure from IVC size and collapse.","F"),
(PH,"Preload refers to:","The stretch of the ventricle at the end of diastole (end-diastolic volume)",["The resistance the ventricle pumps against","Heart rate","The strength of contraction independent of loading"],"Venous return and blood volume affect preload.","F"),
(PH,"Afterload refers to:","The resistance the ventricle must overcome to eject blood",["End-diastolic volume","Venous return","Heart rate"],"Hypertension and aortic stenosis raise LV afterload.","F"),
(PH,"The Frank-Starling mechanism states that:","Greater stretch of the ventricle (within limits) produces a stronger contraction",["Heart rate increases with afterload","Contraction weakens with filling","Valves close with pressure"],"More filling leads to more stroke volume, up to a point.","F"),
(PH,"Stroke volume is determined by:","Preload, afterload and contractility",["Heart rate only","Valve area only","Blood pressure only"],"Cardiac output = stroke volume × heart rate.","F"),
(PH,"During exercise, cardiac output rises mainly through:","Increased heart rate and stroke volume",["Decreased heart rate","Lower contractility","Higher afterload"],"Stress echo looks for the expected increase in wall motion and EF.","F"),
(PH,"Normal oxygen saturation in the right atrium is about:","75%",["98%","50%","100%"],"Left heart blood is about 95% to 100%. A step-up in right-sided saturation suggests a left-to-right shunt.","C"),
(PH,"The 'v' wave in the atrial or jugular venous pressure tracing reflects:","Atrial filling against a closed AV valve during ventricular systole",["Atrial contraction","AV valve closure","Ventricular relaxation"],"Large v waves occur with severe MR or TR. The 'a' wave reflects atrial contraction.","C"),
(PH,"Parasympathetic (vagal) stimulation of the heart causes:","A slower heart rate",["A faster heart rate","Stronger contraction","Higher blood pressure"],"Sympathetic stimulation raises heart rate and contractility.","F"),
(PH,"Isovolumic contraction time is the interval between:","Mitral valve closure and aortic valve opening",["Aortic valve closure and mitral valve opening","Mitral valve opening and closure","Atrial and ventricular contraction"],"It is used in the myocardial performance (Tei) index.","F"),
(PH,"The myocardial performance (Tei) index is calculated as:","(IVCT + IVRT) ÷ ejection time",["Ejection time ÷ IVRT","SV ÷ EDV","E ÷ e′"],"A higher index means worse global function. It can be measured for both ventricles.","C"),
# --- Echo views ---
(EV,"The right parasternal view is mainly used to:","Align CW Doppler with an aortic stenosis jet",["Measure LV volumes","Image the LA appendage","Assess the tricuspid valve"],"The patient lies on the right side; the transducer is placed at the right upper sternal border.","F"),
(EV,"The apical five-chamber view adds which structure to the apical four-chamber view?","LVOT and aortic valve",["Coronary sinus","Pulmonic valve","Descending aorta"],"It is obtained by tilting anteriorly and is used for LVOT and AV Doppler.","F"),
(EV,"The coronary sinus is best seen in an apical view by:","Tilting the transducer posteriorly from the four-chamber view",["Tilting anteriorly","Rotating to the two-chamber view","Moving to the suprasternal notch"],"It appears as a tube running along the back of the heart into the RA.","F"),
(EV,"Which wall segments are seen in the parasternal long-axis view?","Anteroseptal and inferolateral",["Anterior and inferior","Inferoseptal and anterolateral","Lateral and septal only"],"The A3C shows the same walls from the apex.","F"),
(EV,"In the apical four-chamber view, which LV walls are seen?","Inferoseptal and anterolateral",["Anterior and inferior","Anteroseptal and inferolateral","Posterior and anterior"],"A2C shows anterior and inferior walls; A3C shows anteroseptal and inferolateral.","F"),
(EV,"The parasternal short-axis view at the papillary muscle level shows which LV segments?","All six mid-ventricular segments",["Only the apical cap","Only the basal septum","The mitral leaflets"],"It is useful for checking wall motion in all three coronary territories at once.","F"),
(EV,"The suprasternal short-axis view shows the left atrium with all four pulmonary veins entering, called the:","'Crab' view",["Mercedes-Benz sign","Fish-mouth view","Hockey-stick view"],"The aortic arch is seen in cross-section above the right pulmonary artery.","C"),
(EV,"The subcostal short-axis view is useful for:","Seeing the LV and RV in short axis when parasternal windows are poor",["Measuring the aortic arch","Recording AS velocity","Viewing the LAA"],"It can also show the RVOT and pulmonic valve.","F"),
(EV,"An RV-focused apical four-chamber view is recommended for:","Measuring RV size and function",["Measuring LV EF","Assessing the aortic valve","Measuring LA volume"],"Center the RV and show its full length without foreshortening.","F"),
(EV,"For PW Doppler of the LVOT, the sample volume is placed:","Just below the aortic valve in the apical five-chamber or three-chamber view",["In the left atrium","At the mitral leaflet tips","In the ascending aorta 5 cm above the valve"],"Use the same site where the LVOT diameter is measured for stroke volume.","F"),
(EV,"The right upper pulmonary vein is usually sampled with PW Doppler in the:","Apical four-chamber view, using color to guide placement 1 to 2 cm into the vein",["Parasternal long-axis view","Suprasternal view","Subcostal IVC view"],"It is often seen next to the interatrial septum in the far field.","F"),
(EV,"The hepatic veins are best assessed with Doppler in the:","Subcostal view",["Parasternal long-axis view","Apical two-chamber view","Suprasternal view"],"Hepatic vein flow reflects RA pressure, TR severity and constriction.","F"),
(EV,"The standard M-mode of the aortic root and left atrium is recorded in:","Parasternal long-axis or short-axis view at the level of the aortic valve",["Apical four-chamber view","Subcostal view","Suprasternal view"],"The cursor passes through the RVOT, aortic root and LA.","F"),
(EV,"The parasternal RV outflow view is obtained by:","Tilting anteriorly from the parasternal long-axis view",["Tilting inferiorly toward the right hip","Rotating to the apical view","Moving to the subcostal window"],"It shows the RVOT, pulmonic valve and main PA.","F"),
(EV,"The ASE-recommended imaging depth for a standard PLAX view should:","Include the descending aorta behind the left atrium",["Show only the RV","Stop at the mitral valve","Be the maximum possible"],"Then reduce depth to zoom on structures of interest.","F"),
(EV,"In the mid-esophageal four-chamber TEE view, the probe is at about:","0° to 10°",["90°","120° to 150°","180°"],"It shows all four chambers with the atria at the top of the screen.","F"),
(EV,"The mid-esophageal long-axis TEE view is obtained at about:","120° to 140°",["0°","45°","90°"],"It resembles the PLAX view and shows the LVOT, aortic valve and mitral valve.","F"),
(EV,"The mid-esophageal aortic valve short-axis TEE view is obtained at about:","30° to 45°",["0°","90°","180°"],"It shows all three aortic cusps and is used for planimetry.","F"),
(EV,"The transgastric mid short-axis TEE view is used mainly to:","Monitor LV wall motion and filling",["Image the aortic arch","Measure the LA appendage velocity","Assess the pulmonic valve"],"It is the standard monitoring view in the operating room.","F"),
(EV,"The left atrial appendage on TEE is best seen in the:","Mid-esophageal two-chamber view at about 90°, and other multiplane angles",["Transgastric short-axis view","Deep transgastric view only","Upper esophageal arch view"],"The appendage is examined at several angles because it is often multilobed.","F"),
(EV,"The bicaval TEE view at about 90° to 110° shows:","The SVC and IVC entering the right atrium with the interatrial septum",["The aortic valve in short axis","The LV apex","The pulmonary veins only"],"It is ideal for sinus venosus defects and PFO assessment.","F"),
(EV,"In the suprasternal long-axis view, which direction is flow in the descending aorta?","Away from the transducer, below the baseline",["Toward the transducer","Flow is absent","Toward the transducer in systole only"],"Ascending aorta flow comes toward the transducer.","F"),
(EV,"The parasternal short-axis view at the aortic level shows all of these EXCEPT:","The left ventricular apex",["Aortic valve cusps","Tricuspid valve","Pulmonic valve and RVOT"],"The LA, interatrial septum and coronary origins are also seen at this level.","F"),
(EV,"When imaging the LA for volume, the apical views should be:","Optimized for the LA, avoiding foreshortening of the atrium",["Optimized only for the LV","Recorded in diastole","Taken from the parasternal view only"],"LA-focused views give accurate LA volumes at end-systole.","F"),
(EV,"Which window is usually best for imaging the heart in a patient with severe COPD?","Subcostal",["High left parasternal","Right parasternal only","Suprasternal only"],"Hyperinflated lungs push the heart down and block chest windows.","F"),
(EV,"Which view is used to measure tricuspid annular plane systolic excursion (TAPSE)?","Apical four-chamber, with M-mode through the lateral tricuspid annulus",["Parasternal long-axis","Subcostal IVC view","Suprasternal view"],"Align the M-mode cursor with the direction of annular motion.","F"),
(EV,"Mitral annular tissue Doppler (e′) is measured in the:","Apical four-chamber view, at the septal and lateral annulus",["Parasternal short-axis view","Subcostal view","Suprasternal view"],"Place a small sample volume (about 5 to 10 mm) at the base of each wall.","F"),
(EV,"Planimetry of mitral stenosis is performed in:","Parasternal short-axis at the mitral leaflet tips",["Apical four-chamber","Subcostal","Suprasternal"],"Scan from base to tips to find the smallest orifice.","F"),
]
